-- RealtimeEcommerceAnalytics | SQL-only supervised Naive Bayes, v1
-- Source: deployed Redshift Data API batch f65f8d74-5263-496e-88d4-47374b2a978f (2026-11-21)
-- Trained on 2026-03 through 2026-08; evaluated on 2026-09/10.
-- Requires no SageMaker and creates no SageMaker training jobs.
-- Re-running rebuilds priors and likelihoods; CASCADE safely drops dependent churn views
-- and subsequent CREATE OR REPLACE VIEW statements restore them.
-- Do not run until warehouse source marts are valid and you have inspected the plan.

-- Step 1
CREATE SCHEMA IF NOT EXISTS analytics_ml;

-- Step 2
CREATE OR REPLACE VIEW analytics_ml.churn_features_v1 AS SELECT customer_key,as_of_date,churn_next_30d, CASE WHEN recency_days<=30 THEN '0-30d' WHEN recency_days<=60 THEN '31-60d' WHEN recency_days<=90 THEN '61-90d' ELSE '91+d' END AS recency_bin, CASE WHEN order_count_90d=0 THEN '0' WHEN order_count_90d<=2 THEN '1-2' WHEN order_count_90d<=5 THEN '3-5' ELSE '6+' END AS orders_bin, CASE WHEN spend_90d_gbp<=0 THEN '0' WHEN spend_90d_gbp<200 THEN '(0,200)' WHEN spend_90d_gbp<600 THEN '[200,600)' ELSE '600+' END AS spend_bin, CASE WHEN lifetime_order_count<=1 THEN '1' WHEN lifetime_order_count<=3 THEN '2-3' WHEN lifetime_order_count<=8 THEN '4-8' ELSE '9+' END AS lifetime_bin FROM analytics_marts.mart_customer_churn_training;

-- Step 3
DROP TABLE IF EXISTS analytics_ml.churn_nb_priors_v1 CASCADE;

-- Step 4
CREATE TABLE analytics_ml.churn_nb_priors_v1 AS SELECT churn_next_30d AS label,COUNT(*) AS class_count,(COUNT(*)::DOUBLE PRECISION+1.0)/(SUM(COUNT(*)) OVER()+2.0) AS prior_probability FROM analytics_ml.churn_features_v1 WHERE as_of_date < DATE '2026-09-01' GROUP BY 1;

-- Step 5
DROP TABLE IF EXISTS analytics_ml.churn_nb_likelihoods_v1 CASCADE;

-- Step 6
CREATE TABLE analytics_ml.churn_nb_likelihoods_v1 AS WITH levels AS (SELECT 'recency' AS feature,'0-30d' AS value UNION ALL SELECT 'recency' AS feature,'31-60d' AS value UNION ALL SELECT 'recency' AS feature,'61-90d' AS value UNION ALL SELECT 'recency' AS feature,'91+d' AS value UNION ALL SELECT 'orders' AS feature,'0' AS value UNION ALL SELECT 'orders' AS feature,'1-2' AS value UNION ALL SELECT 'orders' AS feature,'3-5' AS value UNION ALL SELECT 'orders' AS feature,'6+' AS value UNION ALL SELECT 'spend' AS feature,'0' AS value UNION ALL SELECT 'spend' AS feature,'(0,200)' AS value UNION ALL SELECT 'spend' AS feature,'[200,600)' AS value UNION ALL SELECT 'spend' AS feature,'600+' AS value UNION ALL SELECT 'lifetime' AS feature,'1' AS value UNION ALL SELECT 'lifetime' AS feature,'2-3' AS value UNION ALL SELECT 'lifetime' AS feature,'4-8' AS value UNION ALL SELECT 'lifetime' AS feature,'9+' AS value), flat AS (SELECT churn_next_30d AS label,'recency' AS feature,recency_bin AS value FROM analytics_ml.churn_features_v1 WHERE as_of_date < DATE '2026-09-01' UNION ALL SELECT churn_next_30d AS label,'orders' AS feature,orders_bin AS value FROM analytics_ml.churn_features_v1 WHERE as_of_date < DATE '2026-09-01' UNION ALL SELECT churn_next_30d AS label,'spend' AS feature,spend_bin AS value FROM analytics_ml.churn_features_v1 WHERE as_of_date < DATE '2026-09-01' UNION ALL SELECT churn_next_30d AS label,'lifetime' AS feature,lifetime_bin AS value FROM analytics_ml.churn_features_v1 WHERE as_of_date < DATE '2026-09-01'), cnts AS (SELECT label,feature,value,COUNT(*) AS occurrences FROM flat GROUP BY 1,2,3) SELECT lev.feature,lev.value,prior.label,prior.class_count,COALESCE(cnts.occurrences,0) AS occurrences,(COALESCE(cnts.occurrences,0)::DOUBLE PRECISION+1.0)/(prior.class_count+4.0) AS conditional_probability FROM levels lev CROSS JOIN analytics_ml.churn_nb_priors_v1 prior LEFT JOIN cnts ON cnts.feature=lev.feature AND cnts.value=lev.value AND cnts.label=prior.label;

-- Step 7
CREATE OR REPLACE VIEW analytics_ml.churn_nb_predictions_v1 AS WITH examples AS (SELECT customer_key,as_of_date,churn_next_30d AS actual_label,recency_bin,orders_bin,spend_bin,lifetime_bin,'validation' AS cohort FROM analytics_ml.churn_features_v1 WHERE as_of_date>=DATE '2026-09-01' UNION ALL SELECT customer_key,as_of_date,CAST(NULL AS INTEGER),CASE WHEN recency_days<=30 THEN '0-30d' WHEN recency_days<=60 THEN '31-60d' WHEN recency_days<=90 THEN '61-90d' ELSE '91+d' END, CASE WHEN order_count_90d=0 THEN '0' WHEN order_count_90d<=2 THEN '1-2' WHEN order_count_90d<=5 THEN '3-5' ELSE '6+' END, CASE WHEN spend_90d_gbp<=0 THEN '0' WHEN spend_90d_gbp<200 THEN '(0,200)' WHEN spend_90d_gbp<600 THEN '[200,600)' ELSE '600+' END, CASE WHEN lifetime_order_count<=1 THEN '1' WHEN lifetime_order_count<=3 THEN '2-3' WHEN lifetime_order_count<=8 THEN '4-8' ELSE '9+' END,'current' FROM analytics_marts.mart_customer_churn_scoring), flat AS (SELECT customer_key,as_of_date,actual_label,cohort,'recency' AS feature,recency_bin AS value FROM examples UNION ALL SELECT customer_key,as_of_date,actual_label,cohort,'orders' AS feature,orders_bin AS value FROM examples UNION ALL SELECT customer_key,as_of_date,actual_label,cohort,'spend' AS feature,spend_bin AS value FROM examples UNION ALL SELECT customer_key,as_of_date,actual_label,cohort,'lifetime' AS feature,lifetime_bin AS value FROM examples), posterior AS (SELECT f.customer_key,f.as_of_date,f.actual_label,f.cohort,p.label AS candidate_label,LN(p.prior_probability)+SUM(LN(l.conditional_probability)) AS log_probability FROM flat f CROSS JOIN analytics_ml.churn_nb_priors_v1 p JOIN analytics_ml.churn_nb_likelihoods_v1 l ON l.label=p.label AND l.feature=f.feature AND l.value=f.value GROUP BY f.customer_key,f.as_of_date,f.actual_label,f.cohort,p.label,p.prior_probability), log_odds AS (SELECT customer_key,as_of_date,actual_label,cohort,MAX(CASE WHEN candidate_label=0 THEN log_probability END) AS log_p0,MAX(CASE WHEN candidate_label=1 THEN log_probability END) AS log_p1 FROM posterior GROUP BY 1,2,3,4) SELECT customer_key,as_of_date,actual_label,cohort,CAST(1.0/(1.0+EXP(log_p0-log_p1)) AS DECIMAL(10,6)) AS churn_probability,CASE WHEN log_p1>=log_p0 THEN 1 ELSE 0 END AS predicted_label FROM log_odds;

-- Step 8
CREATE OR REPLACE VIEW analytics_ml.churn_nb_validation_metrics_v1 AS WITH v AS (SELECT actual_label,predicted_label,churn_probability FROM analytics_ml.churn_nb_predictions_v1 WHERE cohort='validation'), counts AS (SELECT COUNT(*) AS examples,SUM(CASE WHEN actual_label=1 AND predicted_label=1 THEN 1 ELSE 0 END) AS tp,SUM(CASE WHEN actual_label=0 AND predicted_label=0 THEN 1 ELSE 0 END) AS tn,SUM(CASE WHEN actual_label=0 AND predicted_label=1 THEN 1 ELSE 0 END) AS fp,SUM(CASE WHEN actual_label=1 AND predicted_label=0 THEN 1 ELSE 0 END) AS fn,SUM(actual_label) AS positive_examples FROM v),by_score AS (SELECT churn_probability,SUM(CASE WHEN actual_label=1 THEN 1 ELSE 0 END) AS positives,SUM(CASE WHEN actual_label=0 THEN 1 ELSE 0 END) AS negatives FROM v GROUP BY 1), scored AS (SELECT churn_probability,positives,negatives,COALESCE(SUM(negatives) OVER (ORDER BY churn_probability ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS neg_before FROM by_score),auc AS (SELECT SUM(positives*(neg_before+0.5*negatives)) AS rank_pairs FROM scored) SELECT c.examples,c.tp,c.tn,c.fp,c.fn,c.positive_examples,ROUND((c.tp+c.tn)::DECIMAL(18,5)/NULLIF(c.examples,0),4) AS accuracy,ROUND(c.tp::DECIMAL(18,5)/NULLIF(c.tp+c.fp,0),4) AS precision,ROUND(c.tp::DECIMAL(18,5)/NULLIF(c.tp+c.fn,0),4) AS recall,ROUND(2.0*c.tp/NULLIF(2.0*c.tp+c.fp+c.fn,0),4) AS f1,ROUND(a.rank_pairs/NULLIF(c.positive_examples*(c.examples-c.positive_examples),0),4) AS roc_auc,ROUND(GREATEST(c.positive_examples,c.examples-c.positive_examples)::DECIMAL(18,5)/NULLIF(c.examples,0),4) AS majority_baseline_accuracy FROM counts c CROSS JOIN auc a;

-- Step 9
CREATE OR REPLACE VIEW analytics_ml.churn_nb_score_segments_v1 AS SELECT CASE WHEN churn_probability>=0.8 THEN 'Very high (80%+)' WHEN churn_probability>=0.6 THEN 'High (60-80%)' WHEN churn_probability>=0.4 THEN 'Medium (40-60%)' WHEN churn_probability>=0.2 THEN 'Low (20-40%)' ELSE 'Very low (<20%)' END AS segment,COUNT(*) AS customer_count,ROUND(AVG(churn_probability),4) AS average_predicted_risk FROM analytics_ml.churn_nb_predictions_v1 WHERE cohort='current' GROUP BY 1;
